/**
 * Provenance golden — ONE value crossing the Rust→TS boundary.
 *
 * `provenance.json` is GENERATED by the desktop crate's engine test
 * (`search::tests::search_over_a_real_corpus_returns_provenance_bearing_hits`):
 * it runs a real hybrid search over the `fixture` corpus and writes the real
 * hit's `startLine` for `doc`. This test READS that committed file, renders the
 * SAME fixture through the real `MarkdownReader`, feeds the SAME `startLine` to
 * `scrollToLine`, and asserts the landed block's stamped
 * `[data-line-start, data-line-end]` range CONTAINS it. If the chunker changes
 * the section's start line, the engine test rewrites the JSON and this test
 * follows it — the contract test the plan demands.
 */

import { cleanup, render } from '@testing-library/react';
import { afterEach, expect, test, vi } from 'vitest';
import { createRef } from 'react';
import { MarkdownReader, type MarkdownReaderHandle } from '@mdreader/ui';
import { parseMarkdown } from '@mdreader/markdown';

import golden from './provenance.json';

afterEach(cleanup);

/** The stamped source range of a landed block wrapper (the inner element carries
 *  the `data-line-*` provenance; the wrapper carries only `data-block-index`). */
function landedRange(wrapper: HTMLElement): { start: number; end: number } {
  const stamped = wrapper.matches('[data-line-start]')
    ? wrapper
    : wrapper.querySelector<HTMLElement>('[data-line-start]');
  expect(stamped, 'landed block carries a data-line stamp').toBeTruthy();
  return {
    start: Number(stamped!.getAttribute('data-line-start')),
    end: Number(stamped!.getAttribute('data-line-end')),
  };
}

test("the engine's real hit start_line lands on the block whose data-line range contains it", () => {
  const scrollIntoView = vi.fn();
  Element.prototype.scrollIntoView = scrollIntoView;

  // golden.startLine is a REAL hybrid-search hit's start_line for golden.doc,
  // produced by the engine test and committed to provenance.json — the single
  // value crossing the boundary. Neither derived from the reader's stamps nor
  // hardcoded here.
  const doc = parseMarkdown(golden.fixture);
  const ref = createRef<MarkdownReaderHandle>();
  render(<MarkdownReader doc={doc} ref={ref} />);

  ref.current!.scrollToLine(golden.startLine);
  expect(scrollIntoView).toHaveBeenCalledTimes(1);

  const landed = scrollIntoView.mock.instances[0] as HTMLElement;
  const range = landedRange(landed);
  // Containment — the whole point of the line-range ↔ landed-block contract.
  expect(range.start).toBeLessThanOrEqual(golden.startLine);
  expect(range.end).toBeGreaterThanOrEqual(golden.startLine);
  // And it is genuinely the section the hit named.
  expect(landed.textContent).toContain('Storage engine');
});
